-- create-table BANK_ACCOUNTS
CREATE TABLE "BANK_ACCOUNTS" (
  "/RT/TENANT" TEXT NOT NULL,
  "COMPANY_ID" TEXT NOT NULL,
  "ACCOUNT_NO" INTEGER NOT NULL,
  "IBAN" TEXT NOT NULL,
  "BALANCE" INTEGER NOT NULL DEFAULT 0,
  "OPENED_AT" TEXT,
  CONSTRAINT "BANK_ACCOUNTS#PK" PRIMARY KEY ("/RT/TENANT", "COMPANY_ID", "ACCOUNT_NO"),
  CONSTRAINT "BANK_ACCOUNTS#FK#/RT/TENANT" FOREIGN KEY ("/RT/TENANT") REFERENCES "/RT/TENANTS" ("TENANT"),
  CONSTRAINT "BANK_ACCOUNTS#FK#COMPANY" FOREIGN KEY ("/RT/TENANT", "COMPANY_ID") REFERENCES "COMPANIES" ("/RT/TENANT", "COMPANY_ID"),
  CONSTRAINT "BANK_ACCOUNTS#CK#/RT/TENANT" CHECK ("/RT/TENANT" IS NULL OR (length("/RT/TENANT") <= 16)),
  CONSTRAINT "BANK_ACCOUNTS#CK#COMPANY_ID" CHECK ("COMPANY_ID" IS NULL OR (length("COMPANY_ID") <= 10)),
  CONSTRAINT "BANK_ACCOUNTS#CK#ACCOUNT_NO" CHECK ("ACCOUNT_NO" IS NULL OR ("ACCOUNT_NO" BETWEEN -2147483648 AND 2147483647)),
  CONSTRAINT "BANK_ACCOUNTS#CK#IBAN" CHECK ("IBAN" IS NULL OR (length("IBAN") <= 34)),
  CONSTRAINT "BANK_ACCOUNTS#CK#BALANCE" CHECK ("BALANCE" IS NULL OR ("BALANCE" BETWEEN -999999999999999 AND 999999999999999)),
  CONSTRAINT "BANK_ACCOUNTS#CK#OPENED_AT" CHECK ("OPENED_AT" IS NULL OR ("OPENED_AT" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', substr("OPENED_AT", 1, 19)) IS substr("OPENED_AT", 1, 19)))
) STRICT;

-- create-table COMPANIES
CREATE TABLE "COMPANIES" (
  "/RT/TENANT" TEXT NOT NULL,
  "COMPANY_ID" TEXT NOT NULL,
  "NAME" TEXT NOT NULL,
  "COUNTRY" TEXT NOT NULL,
  "STATUS" TEXT NOT NULL DEFAULT 'ACTIVE',
  "CAPITAL" INTEGER,
  "FOUNDED_ON" TEXT,
  "/TROTTO/OTTO_ID" TEXT,
  CONSTRAINT "COMPANIES#PK" PRIMARY KEY ("/RT/TENANT", "COMPANY_ID"),
  CONSTRAINT "COMPANIES#FK#/RT/TENANT" FOREIGN KEY ("/RT/TENANT") REFERENCES "/RT/TENANTS" ("TENANT"),
  CONSTRAINT "COMPANIES#FK#COUNTRY" FOREIGN KEY ("COUNTRY") REFERENCES "COUNTRIES" ("COUNTRY_CODE"),
  CONSTRAINT "COMPANIES#CK#/RT/TENANT" CHECK ("/RT/TENANT" IS NULL OR (length("/RT/TENANT") <= 16)),
  CONSTRAINT "COMPANIES#CK#COMPANY_ID" CHECK ("COMPANY_ID" IS NULL OR (length("COMPANY_ID") <= 10)),
  CONSTRAINT "COMPANIES#CK#NAME" CHECK ("NAME" IS NULL OR (length("NAME") <= 80)),
  CONSTRAINT "COMPANIES#CK#COUNTRY" CHECK ("COUNTRY" IS NULL OR (length("COUNTRY") <= 2)),
  CONSTRAINT "COMPANIES#CK#STATUS" CHECK ("STATUS" IS NULL OR (length("STATUS") <= 10 AND "STATUS" IN ('ACTIVE', 'BLOCKED', 'CLOSED'))),
  CONSTRAINT "COMPANIES#CK#CAPITAL" CHECK ("CAPITAL" IS NULL OR ("CAPITAL" BETWEEN -999999999999999 AND 999999999999999)),
  CONSTRAINT "COMPANIES#CK#FOUNDED_ON" CHECK ("FOUNDED_ON" IS NULL OR ("FOUNDED_ON" IS date("FOUNDED_ON"))),
  CONSTRAINT "COMPANIES#CK#/TROTTO/OTTO_ID" CHECK ("/TROTTO/OTTO_ID" IS NULL OR (length("/TROTTO/OTTO_ID") <= 20))
) STRICT;

-- create-table COUNTRIES
CREATE TABLE "COUNTRIES" (
  "COUNTRY_CODE" TEXT NOT NULL,
  "NAME" TEXT NOT NULL,
  "CURRENCY" TEXT,
  CONSTRAINT "COUNTRIES#PK" PRIMARY KEY ("COUNTRY_CODE"),
  CONSTRAINT "COUNTRIES#CK#COUNTRY_CODE" CHECK ("COUNTRY_CODE" IS NULL OR (length("COUNTRY_CODE") <= 2)),
  CONSTRAINT "COUNTRIES#CK#NAME" CHECK ("NAME" IS NULL OR (length("NAME") <= 80)),
  CONSTRAINT "COUNTRIES#CK#CURRENCY" CHECK ("CURRENCY" IS NULL OR (length("CURRENCY") <= 3))
) STRICT;

